import { DEFAULT_SKILL_INSTALL_CONFIG, type SkillInstallModelConfig } from './skill-install-config';

export type ModelTier = 'top' | 'high' | 'mid' | 'low';
export type ModelBrand = 'openai' | 'anthropic';
export type ModelCapabilityLevel = 1 | 2 | 2.5 | 3 | 4;
export type AutoTaskKind = 'apiDispatch' | 'singleAsset' | 'routine' | 'complex' | 'modelEdit' | 'veryComplex' | 'unclear';
export type ConfiguredModel = {
  model: string; displayName: string; brand: ModelBrand; tier: ModelTier; priority: number;
  showInModelMenu: boolean; participatesInAuto: boolean; isAutoClassifier: boolean; reasoningEffort?: string;
  capabilityLevel?: ModelCapabilityLevel;
  isNew?: boolean;
};
export type AvailableModel = {
  model: string; hidden?: boolean; defaultReasoningEffort?: string;
  supportedReasoningEfforts?: Array<{ reasoningEffort: string }>;
};
export type ModelConfig = {
  version: number; models: readonly ConfiguredModel[];
  autoRoutes: Record<AutoTaskKind, { tier: ModelTier; preferredModel?: string }>;
  autoClassifier: { reasoningEffort: string; maxOutputTokens: number; timeoutMs: number; maxTaskContextChars: number };
  skillInstall: Readonly<SkillInstallModelConfig>;
};

export const DEFAULT_MODEL = 'gpt-6-astra';
export const AUTO_MODEL = 'auto';
export const TIER_LEVEL: Record<ModelTier, 1 | 2 | 3 | 4> = { low: 1, mid: 2, high: 3, top: 4 };
export const AUTO_TASK_KINDS: readonly AutoTaskKind[] = ['apiDispatch', 'singleAsset', 'routine', 'complex', 'modelEdit', 'veryComplex', 'unclear'];
export const MODEL_CONFIG: ModelConfig = {
  version: 5,
  skillInstall: DEFAULT_SKILL_INSTALL_CONFIG,
  models: [
    { model: DEFAULT_MODEL, displayName: 'GPT-6 Astra', brand: 'openai', tier: 'top', priority: 0, showInModelMenu: true, participatesInAuto: true, isAutoClassifier: false, reasoningEffort: 'high', capabilityLevel: 4 },
    { model: 'gpt-6.1-sol', displayName: 'GPT-6.1 Sol', brand: 'openai', tier: 'high', priority: 0, showInModelMenu: true, participatesInAuto: true, isAutoClassifier: true, reasoningEffort: 'high', capabilityLevel: 3 },
    { model: 'claude-opus-5.5', displayName: 'Opus 5.5', brand: 'anthropic', tier: 'high', priority: 1, showInModelMenu: true, participatesInAuto: true, isAutoClassifier: false },
    { model: 'gpt-6.1-terra', displayName: 'GPT-6.1 Terra', brand: 'openai', tier: 'high', priority: 2, showInModelMenu: true, participatesInAuto: true, isAutoClassifier: false, reasoningEffort: 'high', capabilityLevel: 2.5 },
    { model: 'gpt-6-sol', displayName: 'GPT-6 Sol', brand: 'openai', tier: 'mid', priority: 0, showInModelMenu: true, participatesInAuto: true, isAutoClassifier: false },
    { model: 'gpt-6-luna', displayName: 'GPT-6 Luna', brand: 'openai', tier: 'low', priority: 0, showInModelMenu: false, participatesInAuto: true, isAutoClassifier: false, reasoningEffort: 'xhigh' },
  ],
  autoRoutes: { apiDispatch: { tier: 'low' }, singleAsset: { tier: 'mid' }, routine: { tier: 'mid' }, complex: { tier: 'high' }, modelEdit: { tier: 'high' }, veryComplex: { tier: 'top' }, unclear: { tier: 'high' } },
  // Initial calibration values; execution effort is never reused for classification.
  autoClassifier: { reasoningEffort: 'low', maxOutputTokens: 1024, timeoutMs: 8000, maxTaskContextChars: 4000 },
};

export function configuredModel(model: string, config = MODEL_CONFIG) {
  return config.models.find(entry => entry.model === model);
}

export function validateModelConfig(config: ModelConfig, available?: readonly AvailableModel[]): string[] {
  const errors: string[] = [];
  if (!Number.isSafeInteger(config.version) || config.version < 1) errors.push('version');
  const ids = new Set<string>();
  for (const model of config.models) {
    if (!model.model || ids.has(model.model) || model.model === AUTO_MODEL) errors.push('model_id');
    ids.add(model.model);
    if (!Object.hasOwn(TIER_LEVEL, model.tier) || !Number.isSafeInteger(model.priority) || model.priority < 0) errors.push('tier_priority');
    if (!model.displayName || !['openai', 'anthropic'].includes(model.brand)) errors.push('model_label');
  }
  const classifier = config.models.filter(model => model.isAutoClassifier);
  if (classifier.length !== 1) errors.push('classifier_count');
  if (!config.models.some(model => model.showInModelMenu)) errors.push('manual_model');
  for (const kind of AUTO_TASK_KINDS) {
    const route = config.autoRoutes[kind];
    if (!route || !Object.hasOwn(TIER_LEVEL, route.tier)) errors.push('route_tier');
    if (route?.preferredModel) {
      const preferred = configuredModel(route.preferredModel, config);
      if (!preferred?.participatesInAuto || preferred.tier !== route.tier) errors.push('preferred_model');
    }
  }
  const settings = config.autoClassifier;
  if (!settings.reasoningEffort || [settings.maxOutputTokens, settings.timeoutMs, settings.maxTaskContextChars]
    .some(value => !Number.isSafeInteger(value) || value <= 0)) errors.push('classifier_settings');
  if (available) {
    const usable = available.filter(model => !model.hidden);
    const fallbackLevel = config.autoRoutes.unclear && TIER_LEVEL[config.autoRoutes.unclear.tier];
    if (!config.models.some(model => model.participatesInAuto && TIER_LEVEL[model.tier] >= (fallbackLevel ?? Infinity) && usable.some(entry => entry.model === model.model))) errors.push('fallback_unavailable');
    const entry = usable.find(model => model.model === classifier[0]?.model);
    if (entry?.supportedReasoningEfforts && !entry.supportedReasoningEfforts.some(effort => effort.reasoningEffort === settings.reasoningEffort)) errors.push('classifier_effort');
  }
  return [...new Set(errors)];
}

/** Absence of a classifier is a per-request fallback to the configured unclear tier, not an Auto configuration error. */
export function autoModelForTask(kind: AutoTaskKind, available: readonly AvailableModel[], currentModel?: string, config = MODEL_CONFIG): ConfiguredModel | undefined {
  if (validateModelConfig(config, available).length) return undefined;
  const route = config.autoRoutes[kind];
  const current = currentModel ? configuredModel(currentModel, config) : undefined;
  const minimum = Math.max(TIER_LEVEL[route.tier], current ? TIER_LEVEL[current.tier] : 0);
  const usable = config.models.filter(model => model.participatesInAuto && TIER_LEVEL[model.tier] >= minimum
    && available.some(entry => entry.model === model.model && !entry.hidden));
  // Stable same-level conversations do not change model merely because priority changed.
  if (current && TIER_LEVEL[current.tier] >= minimum && usable.some(model => model.model === current.model)) return current;
  return usable.sort((left, right) => TIER_LEVEL[left.tier] - TIER_LEVEL[right.tier]
    || Number(right.model === route.preferredModel) - Number(left.model === route.preferredModel)
    || left.priority - right.priority || left.model.localeCompare(right.model))[0];
}
